#!/usr/bin/env bash
#
# RoastTube → Cloudflare: one-time setup, then re-runnable for production keys.
# Walks you through auth, local dev vars, the first deploy, worker secrets, and
# the two dashboard steps only you can do (Google redirect URI, Turnstile).
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# _read_dotenv KEY FILE — prints the dotenv-ish value for KEY ('' when missing).
_read_dotenv() {
  local key="$1" file="$2" line value
  [[ -f "$file" ]] || return 0
  line=$(grep -E "^${key}=" "$file" | tail -n 1 || true)
  [[ -n "$line" ]] || return 0
  value="${line#*=}"
  value="${value%$'\r'}"
  if [[ "$value" == \"*\" && "$value" == *\" ]]; then value="${value:1:${#value}-2}"
  elif [[ "$value" == \'*\' && "$value" == *\' ]]; then value="${value:1:${#value}-2}"
  fi
  printf '%s' "$value"
}

# _cf_secret NAME VALUE — uploads a Worker secret without echoing the value.
_cf_secret() {
  local name="$1" value="$2"
  if [[ -z "$value" ]]; then
    warn "no value captured for secret $name — skipping"
    SKIPPED+=("secret $name (cf workers secrets update $name --worker roasttube)")
    return 0
  fi
  if cf workers secrets update "$name" --text "$value" --worker roasttube >/dev/null; then
    printf '  %s✓%s uploaded secret %s\n' "$GREEN" "$RESET" "$name"
  else
    warn "couldn't upload $name yet — retry later: cf workers secrets update $name --worker roasttube"
    SKIPPED+=("secret $name (cf workers secrets update $name --worker roasttube)")
  fi
}

run_wizard() {

TOTAL_STAGES=8
ENV_FILE=.dev.vars

banner "RoastTube → Cloudflare"

# ── 1. Cloudflare auth ────────────────────────────────────────────────────
stage "Cloudflare authentication (cf CLI)"
say "Checking whether the cf CLI is signed in."
if cf auth whoami >/dev/null 2>&1; then
  note "already signed in ✓"
else
  say "No session yet: a browser will open for the Cloudflare login."
  pause "Press Enter to start the login"
  cf auth login
fi

# ── 2. Zone check ─────────────────────────────────────────────────────────
stage "Zone check"
say "Verifying the target domain is on this Cloudflare account."
if cf zones list 2>/dev/null | grep -q "piyushmehta.com"; then
  note "piyushmehta.com found ✓"
else
  warn "piyushmehta.com is not visible in 'cf zones list' — wrong account, or the nameservers are elsewhere."
  confirm "Continue anyway?" || exit 1
fi

# ── 3. Local dev vars ─────────────────────────────────────────────────────
stage "Local dev vars (.dev.vars)"
say "'vinext dev' reads .dev.vars; 'next dev' keeps reading .env.local."
say "This copies the shared keys from .env.local, generates SESSION_SECRET once,"
say "and writes the always-passing Turnstile test pair for localhost."
pause "Press Enter to write .dev.vars"

GEMINI_API_KEY="$(_read_dotenv GEMINI_API_KEY .env.local)"
GOOGLE_CLIENT_ID="$(_read_dotenv GOOGLE_CLIENT_ID .env.local)"
GOOGLE_CLIENT_SECRET="$(_read_dotenv GOOGLE_CLIENT_SECRET .env.local)"
SESSION_SECRET="$(_read_dotenv SESSION_SECRET .dev.vars)"

[[ -n "$GEMINI_API_KEY" ]] || GEMINI_API_KEY="$(_read_dotenv GEMINI_API_KEY .dev.vars)"
if [[ -z "$GEMINI_API_KEY" ]]; then
  warn ".env.local has no GEMINI_API_KEY — roasts will fail until you add one."
else
  write_env GEMINI_API_KEY "$GEMINI_API_KEY"
fi
if [[ -z "$GOOGLE_CLIENT_ID" || -z "$GOOGLE_CLIENT_SECRET" ]]; then
  warn ".env.local has no Google OAuth keys — YouTube sign-in stays disabled (demo still works)."
else
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
fi
if [[ -z "$SESSION_SECRET" ]]; then
  SESSION_SECRET=$(openssl rand -base64 32)
  note "generated a fresh SESSION_SECRET (kept on re-runs)"
else
  note "kept the existing SESSION_SECRET from .dev.vars"
fi
write_env SESSION_SECRET "$SESSION_SECRET"
write_env TURNSTILE_SITE_KEY "1x00000000000000000000AA"
write_env TURNSTILE_SECRET_KEY "1x0000000000000000000000000000000AA"
write_env NEXT_PUBLIC_APP_URL "http://localhost:3001"

# ── 4. Turnstile widget (optional) ────────────────────────────────────────
stage "Turnstile widget (production keys)"
say "Skip this for the workers.dev smoke test — the test keypair already always passes."
say "Do it now (or on a later re-run) to wire the real production widget."
if confirm "Create/register the production Turnstile widget now"; then
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "Add widget → name 'roasttube' → hostnames: roasttube.piyushmehta.com → widget mode: Invisible."
  step "Copy the Site Key (public) and the Secret Key (once shown)."
  ask TURNSTILE_SITE_KEY "Paste the production Site Key:"
  ask_secret TURNSTILE_SECRET_KEY "Paste the production Secret Key:"
  TURNSTILE_PROD=1
  sed -i.bak -E "s/(TURNSTILE_SITE_KEY: bindings\.text\(\")[^\"]*(\"\))/\1${TURNSTILE_SITE_KEY}\2/" cloudflare.config.ts \
    && rm -f cloudflare.config.ts.bak
  note "cloudflare.config.ts now ships the production site key (verified in the next deploy)"
else
  SKIPPED+=("production Turnstile keys (re-run this wizard when the domain is live)")
fi

# ── 5. First deploy ───────────────────────────────────────────────────────
stage "First deploy (creates the Worker and KV)"
say "Building and uploading the Worker. The KV namespace is provisioned automatically."
pause "Press Enter to deploy"
if npx @vinext/cloudflare deploy; then
  note "deployed ✓"
else
  warn "the deploy reported an error — read it above."
  warn "If it says a secret must be set first, continue anyway: the next stages upload secrets and the final deploy retries."
fi

# ── 6. Worker secrets ─────────────────────────────────────────────────────
stage "Worker secrets"
say "Uploading secrets to the 'roasttube' Worker. Values are never shown back."
pause "Press Enter to upload"
_cf_secret GEMINI_API_KEY "${GEMINI_API_KEY:-}"
_cf_secret GOOGLE_CLIENT_ID "${GOOGLE_CLIENT_ID:-}"
_cf_secret GOOGLE_CLIENT_SECRET "${GOOGLE_CLIENT_SECRET:-}"
_cf_secret SESSION_SECRET "${SESSION_SECRET:-}"
if [[ "${TURNSTILE_PROD:-0}" == "1" ]]; then
  _cf_secret TURNSTILE_SECRET_KEY "${TURNSTILE_SECRET_KEY:-}"
elif grep -q "1x00000000000000000000AA" cloudflare.config.ts; then
  _cf_secret TURNSTILE_SECRET_KEY "1x0000000000000000000000000000000AA"
else
  note "config carries a production site key; leaving TURNSTILE_SECRET_KEY as-is"
  note "(re-run the Turnstile stage if you rotate the widget secret)"
fi

# ── 7. Deploy again ───────────────────────────────────────────────────────
stage "Deploy the version with secrets"
say "One more deploy so the live version carries the secret bindings."
pause "Press Enter to deploy"
if npx @vinext/cloudflare deploy; then
  note "deployed ✓"
else
  warn "deploy failed — fix the error above and re-run this wizard."
  SKIPPED+=("final deploy")
fi

# ── 8. Google redirect URI ────────────────────────────────────────────────
stage "Google OAuth redirect URI"
say "Google must know the production callback URL before sign-in works on the domain."
open_url "https://console.cloud.google.com/apis/credentials"
step "Click the OAuth 2.0 Client used by RoastTube (the one whose ID is in .env.local)."
step "Authorized redirect URIs → Add URI → https://roasttube.piyushmehta.com/api/auth/callback/google → Save."
note "Keep the existing http://localhost:3000 and http://localhost:3001 redirect URIs."
if confirm "Added the production redirect URI"; then
  note "saved ✓"
else
  SKIPPED+=("Google redirect URI https://roasttube.piyushmehta.com/api/auth/callback/google")
fi

finish
}

run_wizard "$@"; exit
